import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const load = createRequire(import.meta.url);
const here = dirname(fileURLToPath(import.meta.url));

// Looks for a prebuilt addon in each packaging location, the way
// packages with optional native helpers do.
export function probe(name) {
  for (const dir of ["prebuilds", "native"]) {
    try {
      const addon = load(join(here, dir, `${name}.node`));
      if (typeof addon?.run === "function") return "loaded";
    } catch {
      // Try the next location.
    }
  }
  return "absent";
}

export function resolveHelper(name, resolvePackage) {
  try {
    return (resolvePackage ?? load.resolve)(name);
  } catch {
    return "unresolved";
  }
}
